--
-- TOC entry 256 (class 1259 OID 57508)
-- Name: vw_audience_performance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_audience_performance AS
 SELECT ta.audience_id,
    ta.tournament_id,
    t.year,
    ta.metric_name,
    ta.audience_value_millions,
    ta.measurement_type,
    ta.data_status,
    ta.notes
   FROM (public.tournament_audience ta
     JOIN public.tournaments t ON ((t.tournament_id = ta.tournament_id)));


ALTER VIEW public.vw_audience_performance OWNER TO postgres;

