CREATE VIEW public.vw_financial_performance AS
 SELECT tf.financial_id,
    tf.tournament_id,
    t.year,
    tf.world_cup_revenue_millions,
    tf.broadcasting_revenue_millions,
    tf.marketing_revenue_millions,
    tf.ticketing_revenue_millions,
    tf.hospitality_revenue_millions,
    tf.licensing_revenue_millions,
    tf.world_cup_cost_millions,
    tf.world_cup_surplus_millions,
    tf.reporting_basis,
    tf.data_status,
    tf.as_of_date,
    tf.fifa_annual_revenue_budget_millions,
    tf.annual_broadcasting_budget_millions,
    tf.annual_marketing_budget_millions,
    tf.annual_hospitality_ticketing_budget_millions,
    tf.annual_licensing_budget_millions
   FROM (public.tournament_financials tf
     JOIN public.tournaments t ON ((tf.tournament_id = t.tournament_id)));


ALTER VIEW public.vw_financial_performance OWNER TO postgres;

--
-- TOC entry 258 (class 1259 OID 57518)
-- Name: vw_host_footprint; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_host_footprint AS
 SELECT t.tournament_id,
    t.year,
    t.host_country,
    v.venue_id,
    v.stadium_name,
    v.city,
    v.country,
    v.latitude,
    v.longitude,
    tv.capacity AS tournament_capacity,
    count(m.match_id) AS matches_hosted,
    sum(ma.attendance) AS total_attendance,
    round(avg(ma.attendance), 0) AS avg_attendance_per_match,
    round((((sum(ma.attendance))::numeric * 100.0) / (sum(ma.available_capacity))::numeric), 2) AS capacity_utilization
   FROM ((((public.tournaments t
     JOIN public.tournament_venues tv ON ((tv.tournament_id = t.tournament_id)))
     JOIN public.venues v ON ((v.venue_id = tv.venue_id)))
     LEFT JOIN public.matches m ON (((m.tournament_id = t.tournament_id) AND (m.venue_id = v.venue_id))))
     LEFT JOIN public.match_attendance ma ON ((ma.match_id = m.match_id)))
  GROUP BY t.tournament_id, t.year, t.host_country, v.venue_id, v.stadium_name, v.city, v.country, v.latitude, v.longitude, tv.capacity;


ALTER VIEW public.vw_host_footprint OWNER TO postgres;

