--

CREATE VIEW public.vw_sporting_performance AS
 WITH match_summary AS (
         SELECT t.tournament_id,
            t.year,
            count(m.match_id) AS matches_played,
            sum((m.home_score + m.away_score)) AS total_goals,
            round((((sum((m.home_score + m.away_score)))::numeric * 1.0) / (count(m.match_id))::numeric), 2) AS goals_per_match,
            count(
                CASE
                    WHEN (m.home_score = m.away_score) THEN 1
                    ELSE NULL::integer
                END) AS drawn_matches,
            count(
                CASE
                    WHEN (abs((m.home_score - m.away_score)) = 1) THEN 1
                    ELSE NULL::integer
                END) AS one_goal_margin_matches,
            count(
                CASE
                    WHEN (abs((m.home_score - m.away_score)) >= 3) THEN 1
                    ELSE NULL::integer
                END) AS three_plus_goal_margin_matches
           FROM (public.matches m
             JOIN public.tournaments t ON ((t.tournament_id = m.tournament_id)))
          GROUP BY t.tournament_id, t.year
        ), event_summary AS (
         SELECT t.tournament_id,
            count(
                CASE
                    WHEN ((wme.event_type)::text = 'Yellow Card'::text) THEN 1
                    ELSE NULL::integer
                END) AS yellow_cards,
            count(
                CASE
                    WHEN ((wme.event_type)::text = 'Red Card'::text) THEN 1
                    ELSE NULL::integer
                END) AS red_cards,
            count(
                CASE
                    WHEN ((wme.event_type)::text = 'Second Yellow Card'::text) THEN 1
                    ELSE NULL::integer
                END) AS second_yellow_cards,
            count(
                CASE
                    WHEN ((wme.event_type)::text = 'Own Goal'::text) THEN 1
                    ELSE NULL::integer
                END) AS own_goals,
            count(
                CASE
                    WHEN ((wme.event_type)::text = 'VAR Review'::text) THEN 1
                    ELSE NULL::integer
                END) AS var_reviews
           FROM ((public.worldcup_match_events wme
             JOIN public.matches m ON ((m.match_id = wme.match_id)))
             JOIN public.tournaments t ON ((t.tournament_id = m.tournament_id)))
          GROUP BY t.tournament_id
        ), discipline_2026 AS (
         SELECT ( SELECT count(*) AS count
                   FROM (public.staging_2026_appearances s
                     CROSS JOIN LATERAL regexp_split_to_table(TRIM(BOTH FROM s.yellow_card_minutes), '\s+'::text) yellow_minute(yellow_minute))
                  WHERE ((s.yellow_card_minutes IS NOT NULL) AND (s.yellow_card_minutes <> ''::text))) AS yellow_cards,
            count(*) FILTER (WHERE ((staging_2026_appearances.red_card_minutes IS NOT NULL) AND (staging_2026_appearances.red_card_minutes <> ''::text))) AS red_cards,
            count(*) FILTER (WHERE (staging_2026_appearances.yellow_card_minutes ~ '\s+'::text)) AS second_yellow_cards
           FROM public.staging_2026_appearances
        )
 SELECT ms.tournament_id,
    ms.year,
    ms.matches_played,
    ms.total_goals,
    ms.goals_per_match,
    ms.drawn_matches,
    ms.one_goal_margin_matches,
    ms.three_plus_goal_margin_matches,
        CASE
            WHEN (ms.year = 2026) THEN d.yellow_cards
            ELSE COALESCE(es.yellow_cards, (0)::bigint)
        END AS yellow_cards,
        CASE
            WHEN (ms.year = 2026) THEN d.red_cards
            ELSE COALESCE(es.red_cards, (0)::bigint)
        END AS red_cards,
        CASE
            WHEN (ms.year = 2026) THEN d.second_yellow_cards
            ELSE COALESCE(es.second_yellow_cards, (0)::bigint)
        END AS second_yellow_cards,
    COALESCE(es.own_goals, (0)::bigint) AS own_goals,
    COALESCE(es.var_reviews, (0)::bigint) AS var_reviews,
        CASE
            WHEN (ms.year = 2026) THEN 'Complete discipline coverage; partial other event coverage'::text
            ELSE 'Complete event coverage'::text
        END AS event_data_status
   FROM ((match_summary ms
     LEFT JOIN event_summary es ON ((es.tournament_id = ms.tournament_id)))
     LEFT JOIN discipline_2026 d ON ((ms.year = 2026)));


ALTER VIEW public.vw_sporting_performance OWNER TO postgres;

--
-- TOC entry 251 (class 1259 OID 57453)
-- Name: vw_stadium_performance; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_stadium_performance AS
 SELECT t.tournament_id,
    t.year,
    v.venue_id,
    v.stadium_name,
    v.city,
    v.country,
    count(m.match_id) AS matches_played,
    sum(ma.attendance) AS total_attendance,
    round((((sum(ma.attendance))::numeric * 1.0) / (count(m.match_id))::numeric)) AS avg_attendance_per_match,
    sum(ma.available_capacity) AS total_available_capacity,
    round((((sum(ma.attendance))::numeric * 100.0) / (sum(ma.available_capacity))::numeric), 2) AS capacity_utilization,
        CASE
            WHEN ((v.stadium_name)::text ~~ 'San Francisco Bay Area Stadium%'::text) THEN 'San Francisco'::character varying
            WHEN ((v.stadium_name)::text ~~ 'New York New Jersey Stadium%'::text) THEN 'New York / New Jersey'::character varying
            WHEN ((v.stadium_name)::text ~~ '%(%'::text) THEN (TRIM(BOTH FROM split_part((v.stadium_name)::text, '('::text, 1)))::character varying
            ELSE v.stadium_name
        END AS stadium_display_name
   FROM (((public.venues v
     JOIN public.matches m ON ((m.venue_id = v.venue_id)))
     JOIN public.match_attendance ma ON ((ma.match_id = m.match_id)))
     JOIN public.tournaments t ON ((t.tournament_id = m.tournament_id)))
  GROUP BY t.tournament_id, t.year, v.venue_id, v.stadium_name, v.city, v.country;


ALTER VIEW public.vw_stadium_performance OWNER TO postgres;

