--
-- TOC entry 250 (class 1259 OID 57444)
-- Name: vw_tournament_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_tournament_summary AS
 SELECT t.tournament_id,
    t.year,
    t.number_of_teams,
    t.number_of_matches,
    sum(ma.attendance) AS total_attendance,
    round((((sum(ma.attendance))::numeric * 1.0) / (count(ma.match_id))::numeric)) AS avg_attendance_per_match,
    sum(ma.available_capacity) AS total_available_capacity,
    round((((sum(ma.attendance))::numeric * 100.0) / (sum(ma.available_capacity))::numeric), 2) AS capacity_utilization
   FROM ((public.tournaments t
     JOIN public.matches m ON ((m.tournament_id = t.tournament_id)))
     JOIN public.match_attendance ma ON ((ma.match_id = m.match_id)))
  GROUP BY t.tournament_id, t.year, t.number_of_teams, t.number_of_matches
  ORDER BY t.year;


ALTER VIEW public.vw_tournament_summary OWNER TO postgres;

